First, extracting all slide text. Please run the following Python code to list text per slide:

```python
data_path = "/Data2/v-weilinjin/workshop/AttributeBench/benchmarks/GAIA/2023/validation/a3fbeb63-0e8c-4a11-bff6-0e3b484c3e9c.pptx"

from pptx import Presentation

def get_slide_texts(p):
    prs = Presentation(p)
    slides_out = []
    for idx, slide in enumerate(prs.slides, start=1):
        parts = []
        for shape in slide.shapes:
            if hasattr(shape, "text"):
                t = shape.text
                if t:
                    parts.append(t)
        # notes if available
        if getattr(slide, "has_notes_slide", False):
            try:
                nt = slide.notes_slide.notes_text_frame.text
                if nt:
                    parts.append(nt)
            except Exception:
                pass
        slides_out.append({"slide_number": idx, "text": " ".join(parts)})
    return slides_out

slides = get_slide_texts(data_path)
for s in slides:
    print(f"Slide {s['slide_number']}: {s['text']}\n")
```
